  about: {
    eyebrow: { de: 'Über mich', en: 'About', es: 'Sobre mí' },
    title: { de: 'Praktische Automatisierung zwischen Business, Technik und Nutzererlebnis.', en: 'Practical automation between business, technology, and user experience.', es: 'Automatización práctica entre negocio, tecnología y experiencia de usuario.' },
    paragraphs: [
      { de: 'Ich arbeite an der Schnittstelle von Prozessanalyse, Automatisierung und Softwareentwicklung. Durch Erfahrung in industrieller Automatisierung, Projektmanagement und kundenspezifischen Projekten kenne ich strukturierte Umsetzung und klare Abstimmung.', en: 'I work at the intersection of process analysis, automation, and software development. With experience in industrial automation, project management, and custom projects, I understand structured delivery and clear alignment.', es: 'Trabajo entre análisis de procesos, automatización y desarrollo. Con experiencia en automatización industrial, gestión de proyectos y proyectos a medida, entiendo la ejecución estructurada.' },
      { de: 'Als UX Engineer mit starkem Angular- und TypeScript-Hintergrund achte ich darauf, dass Automatisierungen nicht nur technisch funktionieren, sondern für Teams verständlich und nutzbar bleiben.', en: 'As a UX engineer with a strong Angular and TypeScript background, I make sure automations not only work technically but remain understandable and usable for teams.', es: 'Como UX Engineer con base sólida en Angular y TypeScript, cuido que las automatizaciones sean técnicas, claras y usables.' },
      { de: 'Mein Ziel ist keine übertriebene AI-Show, sondern klare Prozesse, sinnvolle Tools und Lösungen, die im Alltag helfen.', en: 'My goal is not AI hype, but clear processes, suitable tools, and solutions that help in daily work.', es: 'Mi objetivo no es hype de IA, sino procesos claros, herramientas adecuadas y soluciones útiles.' },
    ],
    strengths: [
      { de: 'Prozessautomatisierung mit praktischer Umsetzung', en: 'Process automation with practical implementation', es: 'Automatización de procesos con implementación práctica' },
      { de: 'Angular, TypeScript und interne Business Apps', en: 'Angular, TypeScript, and internal business apps', es: 'Angular, TypeScript y apps internas' },
      { de: 'AI Agents, Copilot, n8n, Make und Microsoft Tools', en: 'AI agents, Copilot, n8n, Make, and Microsoft tools', es: 'Agentes IA, Copilot, n8n, Make y Microsoft' },
    ],
  },
